'use strict';
(() => {
  const render = () => {
    if (!location.hash.startsWith('#/meters') || !window.redlineApi || document.querySelector('[data-live-meter-surface]')) return;
    const host = document.querySelector('#app'); if (!host) return;
    const el = document.createElement('section'); el.className='live-meter-board'; el.dataset.liveMeterSurface='1';
    el.innerHTML='<div class="live-meter-board-head"><div><span class="eyebrow">LIVE CLIENT MARKET METER</span><strong>ES multi-timeframe condition</strong><small data-meter-updated>Loading canonical backend…</small></div><span class="pill gold" data-meter-status>CONNECTING</span></div><div class="live-meter-grid">'+['10m','30m','1h','4h','1d'].map(tf=>`<div class="live-meter-cell"><span>${tf.toUpperCase()}</span><strong data-meter-score="${tf}">—</strong><small data-meter-state="${tf}">—</small></div>`).join('')+'</div>';
    host.prepend(el);
    window.redlineApi.marketMeter('ES').then(({data})=>{const lights=data?.lights||{};['10m','30m','1h','4h','1d'].forEach(tf=>{const d=lights[tf]||{};el.querySelector(`[data-meter-score="${tf}"]`).textContent=d.score==null?'—':Number(d.score).toFixed(1);el.querySelector(`[data-meter-state="${tf}"]`).textContent=d.state||'UNAVAILABLE'});el.querySelector('[data-meter-updated]').textContent=`Updated ${data?.updated_at_utc||'—'}`;const s=el.querySelector('[data-meter-status]');s.textContent='LIVE BACKEND';s.className='pill green'}).catch(()=>{el.querySelector('[data-meter-status]').textContent='UNAVAILABLE'});
  };
  window.addEventListener('hashchange',()=>setTimeout(render,60)); setTimeout(render,150); setInterval(()=>{if(location.hash.startsWith('#/meters')){const old=document.querySelector('[data-live-meter-surface]');if(old)old.remove();render()}},60000);
})();
'use strict';
(() => {
 const renderChartEngines=()=>{if(!location.hash.startsWith('#/chart')||!window.redlineApi||document.querySelector('[data-live-engine-surface]'))return;const host=document.querySelector('#app');if(!host)return;const el=document.createElement('section');el.className='live-engine-board';el.dataset.liveEngineSurface='1';el.innerHTML='<div class="live-meter-board-head"><div><span class="eyebrow">LIVE ENGINE CONTEXT</span><strong>Canonical ES decision chain</strong><small data-engine-updated>Reading backend routes…</small></div><span class="pill gold" data-engine-status>CONNECTING</span></div><div class="live-engine-grid">'+[['engine3','E3 REACTION'],['engine4','E4 VOLUME'],['engine6','E6 PERMISSION'],['engine22','E22 WAVES'],['engine26','E26 LOCATION'],['engine29','E29 TACTICAL']].map(([id,label])=>`<div class="live-engine-cell"><span>${label}</span><strong data-engine-value="${id}">—</strong><small data-engine-detail="${id}">Loading</small></div>`).join('')+'</div>';host.prepend(el);Promise.allSettled([window.redlineApi.engine3('ES'),window.redlineApi.engine4('ES'),window.redlineApi.engine6('ES'),window.redlineApi.activeWaves('ES'),window.redlineApi.engine26('ES'),window.redlineApi.engine29('ES')]).then(rs=>{const labels=['engine3','engine4','engine6','engine22','engine26','engine29'];rs.forEach((r,i)=>{const v=r.status==='fulfilled'?r.value.data:null;const text=v?.state||v?.status||v?.permission||v?.direction||v?.mode||'UNAVAILABLE';const detail=v?.reason||v?.message||v?.updated_at_utc||'Backend response';el.querySelector(`[data-engine-value="${labels[i]}"]`).textContent=String(text).toUpperCase();el.querySelector(`[data-engine-detail="${labels[i]}"]`).textContent=String(detail).slice(0,80)});el.querySelector('[data-engine-updated]').textContent=`Read ${new Date().toISOString()}`;const st=el.querySelector('[data-engine-status]');st.textContent='LIVE BACKEND';st.className='pill green'});};window.addEventListener('hashchange',()=>setTimeout(renderChartEngines,60));setTimeout(renderChartEngines,180);setInterval(()=>{if(location.hash.startsWith('#/chart')){document.querySelector('[data-live-engine-surface]')?.remove();renderChartEngines()}},60000);
})();
